    chunk.emit(1, 42)   # PUSH_INT 42  (opcode value 1)
    chunk.emit(1, 58)   # PUSH_INT 58
    chunk.emit(9)       # ADD
    print("Chunk has", len(chunk), "instructions")
    for i, instr in enumerate(chunk.instructions):
        print(f"  {i:3d}  {instr}")
